section.programlisting:
function row_count(y: i32, n: i32) returns i32 { let ci (2.0 * (y as f32) / (n as f32)) - 1.0 var count: i32 0 var x: i32 0 while x < n { let cr (2.0 * (x as f32) / (n as f32)) - 1.5 var zr: f32 0.0 var zi: f32 0.0 var i: i32 0 var inside true while i < 50 and inside { let tr zr * zr - zi * zi + cr zi := 2.0 * zr * zi + ci zr := tr if zr * zr + zi * zi > 4.0 inside := false i := i + 1 } if inside count := count + 1 x := x + 1 } count }
let n: i32 2000 var counts Vector[i32](n as size_t) for y in n counts.put(y as size_t, row_count(y, n))
var total 0 for c in counts total := total + c print "mandelbrot `n`: `total` points inside"

section.para:
A card has no pages, no strings and no stack to speak of. It has
      numbers, arrays of numbers, and one routine. A parallel
      for is a kernel when its rounds get by with that:

listitem.para:
they read numbers bound outside the loop, and
        elements of a Vector, Slice or
        Array of such numbers, at any index;

the functions they call take and answer such numbers,
        do not call themselves, and are made of the same
        stuff;

section.programlisting:
function scaled(v: i32, k: i32) returns i32 v * k + 1
function caption(i: int) returns String "row `i`"
let n 1000 let k: i32 3 var src Vector[i32](n as size_t) for i in n src.put(i as size_t, (i as i32) % 17)
var out Vector[i32](n as size_t) for i in n out.put(i as size_t, scaled(src[i as size_t], k))
var wide Vector[int](n as size_t) for i in n wide.put(i as size_t, i * i)
var halves Vector[double](n as size_t) for i in n halves.put(i as size_t, (i as double) * 0.5)
var names Vector[String](n as size_t) for i in n names.put(i as size_t, caption(i))
var sum: i32 0 for i in n sum := sum + out[i as size_t] print "`out[999]` `wide[999]` `halves[999]` `names[999]` `sum`"
